import React from 'react';
import CategoryChoiceComponent from './category_choice.component';

interface Props { }

export class MerchandisingComponent extends React.Component<Props> {
  yellow_choice = {
    'name': 'OUI',
    'url': '/users/auth/identification_mode/',
    'className': 'has_fidelity_button_authentification_mode',
    'ico': {
      'style': {
        'fontSize': '68px',
      }
    }
  }

  basic_choice = {
    'name': 'NON',
    'url': '/order/',
    'className': "has_fidelity_button_not",
    'ico': {
      'style': {
        'fontSize': '68px',
      }
    }
  }

  componentDidMount() {
    const merchandising = (window as any).data.merchandising;
    const { img } = merchandising;
    if (img && img.bg) {
      window.document.body.style.backgroundImage = `url(/public/img/merchandising/${img.bg})`
    }
  }

  componentWillUnmount() {
    window.document.body.style.backgroundImage = "url(/public/img/Mur2.png)";
  }

  render(): JSX.Element {
    (window as any).react_history = (this.props as any).history;
    return (
      <CategoryChoiceComponent
        identification_mode={false}
        history={(this.props as any).history}
        title="VOTRE MENU"
        yellow_choice={this.yellow_choice}
        basic_choice={this.basic_choice}
      />
    );
  }
}
