import { has_fidelity_product } from "./../../../../libs/fidelity";
import { you_fid_client } from "./../../../../libs/you_fid_api";

export function burnPoint(client, cart_list) {
  if (!client.is_authenticated()) {
    return Promise.resolve();
  }

  const burn_products = [];
  cart_list = cart_list.slice(1);

  for (let product of cart_list) {
    if (!has_fidelity_product(product)) {
      continue;
    }

    for (let i = 0; i < product.quantity; i++) {
      burn_products.push({ ...product.youfid_product });
    }
  }

  console.log("Found burn products: ", burn_products);
  if (burn_products.length === 0) {
    return Promise.resolve();
  }

  return you_fid_client.burn_point(client.usr_id, burn_products);
}

export function addPointToCustomer(client, shop, cart_list) {
  if (!client.is_authenticated()) {
    return Promise.resolve({ data: { won_pts: 0 } });
  }

  return you_fid_client.add_point_to_the_customer(
    client.qr_code,
    shop.attribution_pts,
    cart_list[0].total_price
  );
}
