import io, { Socket } from "socket.io-client";

function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    var r = (Math.random() * 16) | 0,
      v = c == "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

class CaisseWSClient {
  ws: Socket = undefined;
  caisseDefined = false;
  connected = false;
  address = "";
  eventCallbackMapper = {};
  pingTimeout = undefined;

  public listen(
    address: string,
    onConnected: () => void,
    onDisconnected: () => void
  ) {
    console.log("** WS Caisse: initing connection");
    this.caisseDefined = address && address !== "";
    this.address = address;
    this.eventCallbackMapper = {
      connect: () => {
        console.log("** WS Caisse: Connected...");
        if (client.ws) {
          client.ws.emit("registerterminal", {
            id: uuidv4(),
          });
        }
      },
      close: () => {
        clearTimeout(this.pingTimeout);
        this.connected = false;
      },
      connect_error: (err) => {
        // console.log("Connection to caisse failed");
        this.connected = false;
        console.log("** WS Caisse: Connecting failed", err);
        if (onDisconnected) {
          onDisconnected();
        }
      },
      reconnecting: () => {
        // console.log("Try reconnecting to master caisse ...");
        console.log("** WS Caisse: Try reconnecting");
      },
      disconnect: () => {
        console.log("** WS Caisse: disconnected");
        this.connected = false;
      },
      sync: (payload) => {
        console.log("** WS Caisse: Received sync payload", payload);
        // console.log("Received sync payload: ", payload);
      },
      welcome: () => {
        console.log("** WS Caisse: Welcommed...");
        this.connected = true;
        if (onConnected) {
          onConnected();
        }
      },
    };

    if (!this.ws) {
      this._connect();
    } else if (address !== this.address) {
      this.ws.close();
      this._connect();
    }
  }

  _connect() {
    console.log(`** WS Caisse: Try connecting to ${this.address} ...`);
    this.ws = io(this.address, {
      reconnection: true,
      reconnectionDelay: 100,
      reconnectionDelayMax: 1000,
      timeout: 1000,
    });

    const eventKeys = Object.keys(this.eventCallbackMapper);
    for (const key of eventKeys) {
      this.ws.on(key, this.eventCallbackMapper[key]);
    }
  }

  close() {
    if (this.ws && this.ws.connected) {
      this.ws.close();
      this.connected = false;
    }
  }

  heartbeat() {
    clearTimeout(this.pingTimeout);

    // Use `WebSocket#terminate()`, which immediately destroys the connection,
    // instead of `WebSocket#close()`, which waits for the close timer.
    // Delay should be equal to the interval at which your server
    // sends out pings plus a conservative assumption of the latency.
    this.pingTimeout = setTimeout(() => {
      this.close();
    }, 30000);
  }
}

const client = new CaisseWSClient();
export default client;
