import React from 'react';
import { withTranslation, WithTranslation } from 'react-i18next';
import { connect } from 'react-redux';
import { bindActionCreators } from 'redux';
import { goToPath, logout } from './../../../actions/index';

let this_component: any;
interface Props extends WithTranslation {
  history: any,
  logout: Function,
  goToPath: Function,
  authentification: any,
}
class HeaderNavigationComponent extends React.Component<Props> {
  constructor(props: any) {
    super(props);
    this.state = {
      'authentification': {},
    }
    this.go_to_home.bind(this);
    this.go_to_profile.bind(this);
    this.my_profile_button.bind(this);
  }

  state: any = {
    authentification: {},
  }

  go_to_home() {
    this.props.goToPath({
      'action': 'popin',
      'id': 'cancel_order',
      'from': 'HeaderNavigationComponent',
    });
  }

  go_to_profile() {
    this.props.goToPath({
      'action': 'history',
      'id': "/profile/",
      'from': 'HeaderNavigationComponent',
    });
  }

  my_profile_button(authentification: any): JSX.Element | void {
    let href = window.location.href.split('/')
    if (href[href.length - 2] === 'profile') { return; }

    if (authentification.authenticated) {
      return (
        <div className="little_text box_shadow go_to_profile" onClick={() => this.go_to_profile()}></div>
      )
    }
  }

  render(): JSX.Element {
    const { t } = this.props;

    this_component = this;
    this.state.authentification = this.props.authentification;
    return (
      <div className="fluid-container header_navigation_container">
        <div className="little_text box_shadow go_to_home" onClick={() => this.go_to_home()}>
          {t('navigation.home')}
        </div>
        {this.my_profile_button(this.state.authentification)}
      </div>
    );
  }

  componentDidMount() { }
}

function mapStateToProps(state: any) {
  if (this_component) {
    setTimeout(() => {
      this_component.setState({
        'authentification': state.authentification,
      });
    }, 100);
  }
  return {
    'authentification': state.authentification,
  };
}
function mapDispatchToProps(dispatch: any) {
  return bindActionCreators({
    logout: logout,
    goToPath: goToPath,
  }, dispatch);
}

export default connect(mapStateToProps, mapDispatchToProps)(withTranslation()(HeaderNavigationComponent));
