
import { ADD_TO_CART, EDIT_CART_ITEM, REDUCE_CART, SET_ORDER_ID, UPDATE_CART_ITEM } from './../actions/index';
import { add_product_to_cart_list, calculate_cart, reduce_product_to_cart_list } from './../libs/cart.calculator';
import { has_fidelity_product } from './../libs/fidelity';

interface CartState {
  list: any[];
  edited?: {
    product: any;
    index: number;
  };
  orderId?: string;
}

const INITIAL_STATE: CartState = {
  list: [
    {
      'cart_config': true,
      'total_price': 0,
      'for_type': 'cart_list',
      'product_quantity': 0,
      'open': true,
      'qr_code': '',
    }
  ],
  edited: undefined
}

// const list: any = [];

export default function (state: CartState = INITIAL_STATE, action: any) {
  switch (action.type) {
    // case UPDATE_DATA:
    //   return action.payload;
    case ADD_TO_CART:
      let list = undefined;
      if (action.payload && action.payload.hasOwnProperty('product_list')) {
        for (let p of action.payload.product_list) {
          p = Object.assign({}, p);
          if (p.hasOwnProperty('quantity')) {
            list = add_product_to_cart_list(p, state.list, p.quantity);
          }
        }

        return {
          ...state,
          list: calculate_cart(list || state.list)
        };
      }

      let product: any = {};
      Object.assign(product, action.payload.product);
      let number = product.quantity;
      if (action.payload.hasOwnProperty('number')) {
        number = action.payload.number;
      }

      if (has_fidelity_product(product)) {
        list = add_product_to_cart_list(product, state.list, number);
        return {
          ...state,
          list: calculate_cart(list)
        };
      }

      list = add_product_to_cart_list(product, state.list, number);
      return {
        ...state,
        list: calculate_cart(list)
      };
    case REDUCE_CART:
      product = {};
      const qty: number = action.payload.number || product.quantity;

      if (has_fidelity_product(action.payload.product)) {
        const _items = reduce_product_to_cart_list(action.payload.product, state.list, qty);
        return {
          ...state,
          list: calculate_cart(_items)
        };
      } else {
        Object.assign(product, action.payload.product);
        const _items = reduce_product_to_cart_list(action.payload.product, state.list, action.payload.number);
        return {
          ...state,
          list: calculate_cart(_items)
        };
      }
    case EDIT_CART_ITEM:
      return {
        ...state,
        edited: action.payload ? { ...action.payload } : undefined
      }

    case UPDATE_CART_ITEM:
      const { index, product: cartItem } = action.payload;
      const { list: items } = state;
      items.splice(index, 1, cartItem);

      return {
        list: items,
        edited: {
          index,
          product: cartItem
        }
      };

    case SET_ORDER_ID:
      return {
        ...state,
        orderId: action.payload
      };

    default:
      return state;
  }
}
