const initialState = { connected: true };

export default function caisseReducer(state: any = initialState, action: any) {
  const disableCaisseAvailabilityCheck = (window as any).disableCaisseAvailabilityCheck || false;
  if (disableCaisseAvailabilityCheck) {
    console.log("No caisse availability check!");
    return state;
  }

  switch (action.type) {
    case "CAISSE_CONNECTED":
      return {
        connected: true,
      };
    case "CAISSE_DISCONNECTED":
      return {
        connected: false,
      };
    default:
      return state;
  }
}
