
import React from 'react';
import { connect } from 'react-redux';
import Slider from "react-slick";
import { bindActionCreators } from 'redux';
import { activeHandicappedVersion, goToPath } from './../../../actions/index';
import { staticFile } from './../../../libs/index';

const CONF = !(window as any).data.configuration_page.header ? { 'slider': true } : (window as any).data.configuration_page.header;
const BASIC_SLIDER_FILE = (window as any).data.design_slider.FOR_HEADER.fileList;
const PMR_SLIDER_FILE = (window as any).data.design_slider.FOR_HEADER_PMR.fileList;

function find_product_with_id_only(id) {
  for (let key in (window as any).data.product_list) {
    for (let product of (window as any).data.product_list[key]) {
      if (product.id === id) {
        product.go_to = { 'action': 'category', 'id': parseInt(key) };
        return product;
      }
    }
  }
}

function clickToHeader(line) {
  // event.preventDefault();
  // event.stopPropagation();
  if (line.real_name.slice(0, 3) === 'pdt') {
    // -> Déjà empecher le systèmes d'ajouter plusieurs produits.
    let ProductListComponent = (window as any).components.ProductListComponent
    let product = find_product_with_id_only(parseInt(line.real_name.slice(3,).split('.')[0]));
    if (ProductListComponent.state.selected_product.id === product.id) { return; }
    ProductListComponent.reset();
    ProductListComponent.state.your_selection = [];
    ProductListComponent.click_product(product);
  } else if (line.real_name.slice(0, 5) === 'categ') {
    this_component.props.goToPath({
      'id': parseInt(line.real_name.slice(5,).split('.')[0]),
      'action': 'category',
      'from': 'header',
    });
  }
}

function MapSlider(line) {
  if (this_component.props.handdicap_version.activated) {
    let image_pmr = PMR_SLIDER_FILE[line.index];
    return (
      <>
        <div onClick={() => clickToHeader(line)} style={{ height: '848px' }}>
          <div className="big-header" style={{ backgroundImage: 'url(' + staticFile(image_pmr.ico) + ')' }}>
          </div>
        </div>
      </>
    )
  }

  const page_show = ['/order/'];
  if (page_show.indexOf(window.location.pathname) === -1 || this_component.props.handdicap_version.activated) {
    return (<></>);
  }

  return (
    <>
      <div onClick={() => clickToHeader(line)}
        key="order_header_component"
        className="header mobile-hidden">
        <div style={{ backgroundImage: 'url("' + staticFile(line.ico) + '")' }}>
        </div>
      </div>
    </>
  );
}

function renderReduceButton() {
  if (!this_component.props.handdicap_version.activated) { return (<></>) }
  return (
    <div className={"closeModePmr "}
      onClick={() => this_component.props.activeHandicappedVersion({ 'activated': false })}>
    </div>
  );
}

function ProductCarrousel() {
  var settings: any = {
    cssEase: "linear",
    infinite: true,
    autoplay: true,
  };

  let render_slider: Array<JSX.Element> = [];
  let i = 0;
  for (let line of BASIC_SLIDER_FILE) {
    render_slider.push((<> {MapSlider(line)} </>))
    line.index = i;
    i++;
  }

  return (
    <div className={"header_slider_container " + this_component.props.handdicap_version.activated ? 'pmr_mode' : ''}>
      {renderReduceButton()}
      <Slider {...settings}
        interval={5 * 1000}>
        {render_slider}
      </Slider>
    </div>
  );
}

let this_component;
interface Props {
  activeHandicappedVersion: Function,
  handdicap_version: any,
  goToPath: Function,
};
class HeaderComponent extends React.Component<Props> {
  constructor(props: any) {
    super(props);
  }

  state: any = {
    pathname: undefined,
    loaded: false
  }

  render_slider_header() {
    if (!this.state.loaded) { return (<></>); }
    if (!CONF.slider) { return (<></>); }
    return (<><ProductCarrousel /></>);
  }

  // ############################################################### [SLIDE HEADER].
  // ############################################################### [SINGLE HEADER].
  render_header() {
    const page_show = ['/order/'];
    if (page_show.indexOf(window.location.pathname) === -1 || (this.props as any).handdicap_version.activated) { return (<></>); }
    return (
      <div key="order_header_component" className="header mobile-hidden">
        <div style={{ backgroundImage: 'url("' + staticFile('/public/img/headers/header1052x256.jpg') + '")' }}>
        </div>
      </div>
    )
  }

  render_pmr_header() {
    if (!this.props.handdicap_version.activated) { return (<></>); }
    return (
      <>
        {renderReduceButton()}
        <div style={{ height: '848px' }}>
          <div className="big-header">
            {
              // <div className={"closeModePmr " + (Object.keys({'sq':''}).length===0 ? 'closed' : 'opened') }
              // onClick={() => (this.props as any).activeHandicappedVersion({'activated': false}) }></div>
            }
          </div>
        </div>
      </>
    );
  }

  render_single_header() {
    if (CONF.slider) { return (<></>); }
    return (
      <>
        {this.render_pmr_header()}
        {this.render_header()}
      </>
    )
  }

  render(): JSX.Element {
    this_component = this;
    return (
      <>
        {this.render_single_header()}
        {this.render_slider_header()}
      </>
    );
  }

  componentDidMount() {
    setTimeout(() => {
      this.setState({
        loaded: true,
      })
    }, 1 * 1000);
  }
}

function mapStateToProps(state: any) {
  if (this_component !== undefined && this_component.state.pathname !== window.location.pathname) {
    this_component.setState({
      pathname: window.location.pathname,
    });
  }
  return {
    handdicap_version: state.handdicap_version,
  };
}


function mapDispatchToProps(dispatch: any) {
  return bindActionCreators({
    activeHandicappedVersion,
    goToPath
  }, dispatch);
}

export default connect(mapStateToProps, mapDispatchToProps)(HeaderComponent);
