import React, { FC } from "react";
import { useDispatch, useSelector } from "react-redux";
import Slider from "react-slick";
import { DownCircleFilled, UpCircleFilled } from "@ant-design/icons";

import { goToPath } from "./../../../actions/index";

export const MenuLeftComponent: FC = () => {
  const dispatch = useDispatch();

  const menuList = useSelector((state: any) => state.menu_list);
  const handicapActive = useSelector((state: any) => state.handdicap_version.activated);
  let currentMenu = useSelector((state: any) => state.go_to);
  if (!currentMenu || !currentMenu.id) {
    currentMenu = menuList[0];
  }

  const gotoMenu = (menuLine) => {
    menuLine.from = "menu_left";
    dispatch(goToPath(menuLine));
  };

  const mapItems = (menus) => {
    let mapped = [];
    let i = 0;
    for (let line of menus) {
      if (line.hasOwnProperty("display")) {
        continue;
      }

      console.log('Menu category: ', line);

      mapped.push(
        <div>
          <div
            className={`menu-item box_shadow_light ${
              currentMenu && currentMenu.id === line.id ? "selected" : ""
            }`}
            onClick={() => gotoMenu(line)}
            style={{ backgroundImage: 'url("' + line.ico + '")' }}
            key={"category_" + i}
            data-ico={line.ico}
          >
            <div className="menu-title">{line.name}</div>
          </div>
        </div>
      );

      i++;
    }

    return mapped;
  };

  const settings = {
    dots: false,
    infinite: false,
    slidesToShow: handicapActive ? 3 : 4,
    slidesToScroll: handicapActive ? 3 : 4,
    vertical: true,
    verticalSwiping: true,
    nextArrow: <DownCircleFilled />,
    prevArrow: <UpCircleFilled />
  };

  console.log("Handicap active: ", handicapActive);
  console.log("Slider settings: ", settings);

  return (
    <div className="menu-left-wrapper">
      <Slider
        className="menu-left"
        {...settings}
      >
        {mapItems(menuList)}
      </Slider>
    </div>
  );
};
