import React from "react";
import { connect } from "react-redux";
import { BrowserRouter as Router, Route, Switch } from "react-router-dom";
import { bindActionCreators } from "redux";
import {
  activeHandicappedVersion,
  CAISSE_CONNECTED,
  CAISSE_DISCONNECTED,
  update_data,
  update_product,
} from "./actions/index";
import "./App.css";
import CaisseWSClient from "./CaisseWSClient";
import FirstRunConfigurationComponent from "./components/config/first_run_configuration/first_run_configuration.component";
import HasFidelityCardComponent from "./components/fidelity/has_fidelity_card/has_fidelity_card.component";
import ScanFidelityCardComponent from "./components/fidelity/scan_fidelity_card/scan_fidelity_card.component";
import HomeComponent from "./components/home/home.component";
import { MerchandisingComponent } from "./components/merchandising/MerchandisingComponent";
import AddedToCartComponent from "./components/nav/added_to_cart/added_to_cart.component";
import HeaderComponent from "./components/nav/header/header.component";
import MaintenanceComponent from "./components/nav/maintenance_component/maintenance_component.component";
import PopInComponent from "./components/nav/pop_in/pop_in.component";
import TimerPopinComponent from "./components/nav/timer_popin/timer_popin.component";
import AcceptedPaymentComponent from "./components/order/checkout/accepted_payement/accepted_payement.component";
import CommandTypeComponent from "./components/order/checkout/command_type/command_type.component";
import CreditCardPaymentComponent from "./components/order/checkout/credit_card_payment/credit_card_payment.component";
import SelectPaymentTypeComponent from "./components/order/checkout/select_payment_type/select_payment_type.component";
import SuggestionComponent from "./components/order/checkout/suggestion/suggestion.component";
import TpaErrorComponent from "./components/order/checkout/tpa_error/tpa_error.component";
import OrderComponent from "./components/order/order.component";
import { UnavailableComponent } from "./components/unavailable/unavailable.component";
import IdentificationModeComponent from "./components/users/auth/identification_mode/identification_mode.component";
import IdentificationPageComponent from "./components/users/auth/identification_page/identification_page.component";
import ProfileComponent from "./components/users/profile/profile.component";
import { is_electron_browser } from "./libs/index";
import Tracker from "./libs/tracker";
import { you_fid_client } from "./libs/you_fid_api";
import { caisseConnectedSelector } from "./selectors";

let this_component: any;
class App extends React.Component {
  private connection;

  constructor(props: any) {
    super(props);
    this.load_youfid_api();
      console.log("Init WSocket client ...");
      this.connection = new WebSocket("ws://localhost:3000");
      console.log("WSocket client inited: ", this.connection);

      this.connection.onopen = (e) => {
        console.log("Connection established!");
        this.connection.send(
          JSON.stringify({
            type: "GET_CAISSE_WS_ADDRESS",
          })
        );
      };

      // callback messages
      this.connection.onmessage = (msg) => {
        // console.log("Message DATA received!! ", msg.data);
        const data = JSON.parse(msg.data);
        // console.log("Parsed event data: ", data);
        if (data.type == "CAISSE_WS_ADDRESS") {
          if (CaisseWSClient.connected) {
            CaisseWSClient.close();
          }

          if (data.address && data.address !== "") {
            CaisseWSClient.listen(
              data.address,
              () => {
                props.dispatchAction({
                  type: "CAISSE_CONNECTED",
                });
              },
              () => {
                props.dispatchAction({
                  type: "CAISSE_DISCONNECTED",
                });
              }
            );
          }
        } else if (data.type) {
          // Update product in redux state and window.data
          const disableCaisseAvailabilityCheck = (window as any).disableCaisseAvailabilityCheck || false
          if (data.type != CAISSE_CONNECTED && data.type != CAISSE_DISCONNECTED) {
            props.dispatchAction(data);
          } else if (!disableCaisseAvailabilityCheck) {
            props.dispatchAction(data);
          }
        }
      };

      // Closed window
      this.connection.onclose = (e) => {
        console.log("Connection closed!", e);
      };

      // Error window
      this.connection.onerror = (e) => {
        console.log("Connection error!", e);
      };
    // }
  }

  // -------------------------------------------- DEFINE THE VITAL DATA
  load_youfid_api() {
    you_fid_client.merchant_login("", "").then((e) => {
      you_fid_client.merchant_detail().then((e) => {
        (this.props as any).update_data("shop.init", e.data);
        // this.test_youfid_api();
      });
    });
    // setInterval(() => { this.test_youfid_api(); }, 1000)
  }

  test_youfid_api() {
    you_fid_client.merchant_login("", "").then((e) => {
      console.log(e);
    });
  }

  // -------------------------------------------- APP RENDER
  state: any = {
    real_size_screen: {
      width: 1080,
      height: 1920,
    },
    screen_height: 1920 + "px",
    airbag_style: {},
  };
  fullheight() {
    this.setState({
      screen_height: this.state.real_size_screen.height + "px",
    });
  }

  adapt_screen(handdicap_version: any): void {
    let airbag_style = {};
    let screen_height;
    if (handdicap_version.activated) {
      airbag_style = {
        height: "848px",
      };
      screen_height = (1920 - 848) + "px";
    } else {
      airbag_style = {
        height: "0px",
        backgroundColor: "blue",
      };
      screen_height = "calc(100vh - 274px)";
    }

    this.setState({
      airbag_style: airbag_style,
      screen_height: screen_height,
      handdicap_version,
    });
  }

  render() {
    (window as any).react_history = (this.props as any).history;
    if (!is_electron_browser()) {
      // Modifier la hauteur de l'élément
      var viewportmeta = document.querySelector('meta[name="viewport"]');
      (viewportmeta as any).content =
        "width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no";
      this.updateDimensions(false);
    }
    this.state.handdicap_version = (this.props as any).handdicap_version;
    this_component = this;
    // console.log(this.state.airbag_style)

    if (!(this.props as any).caisseConnected) {
      return (
        <div
          className={[
            "fluid-container",
            "app_global_container",
            this.state.handdicap_version.activated
              ? "handicap_mode_activated"
              : "handicap_mode_deactivate",
            `path_name${window.location.pathname.replace(/\//g, "_")}`.slice(
              0,
              -1
            ),
          ].join(" ")}
          style={{
            height: this.state.screen_height,
          }}
        >
          <UnavailableComponent history={(this.props as any).history} />
        </div>
      );
    }

    return (
      <div>
        <HeaderComponent />
        <PopInComponent></PopInComponent>
        <AddedToCartComponent></AddedToCartComponent>
        <TimerPopinComponent></TimerPopinComponent>
        <Router>
          <div
            className={[
              "fluid-container",
              "app_global_container",
              this.state.handdicap_version.activated
                ? "handicap_mode_activated"
                : "handicap_mode_deactivate",
              `path_name${window.location.pathname.replace(/\//g, "_")}`.slice(
                0,
                -1
              ),
            ].join(" ")}
            style={{
              height: this.state.screen_height,
            }}
          >
            <Switch>
              <Route exact path="/" component={HomeComponent} />
              <Route
                exact
                path="/first_run_configuration/"
                component={FirstRunConfigurationComponent}
              />

              <Route
                exact
                path="/users/auth/identification_mode/"
                component={IdentificationModeComponent}
              />
              <Route
                exact
                path="/users/auth/identification_page/"
                component={IdentificationPageComponent}
              />

              <Route
                exact
                path="/fidelity/has_fidelity_card/"
                component={HasFidelityCardComponent}
              />
              <Route
                exact
                path="/fidelity/scan_fidelity_card/"
                component={ScanFidelityCardComponent}
              />

              <Route
                exact
                path="/merchandising/"
                component={MerchandisingComponent}
              />

              <Route
                exact
                path="/profile/create/"
                component={IdentificationPageComponent}
              />
              <Route exact path="/profile/" component={ProfileComponent} />

              <Route exact path="/order/" component={OrderComponent} />
              <Route
                exact
                path="/order/select_payment_type/"
                component={SelectPaymentTypeComponent}
              />
              <Route
                exact
                path="/order/command_type/"
                component={CommandTypeComponent}
              />

              <Route
                exact
                path="/order/checkout/credit_card_payment/"
                component={CreditCardPaymentComponent}
              />
              <Route
                exact
                path="/order/accepted_payement/"
                component={AcceptedPaymentComponent}
              />
              <Route
                exact
                path="/order/suggestion/"
                component={SuggestionComponent}
              />
              <Route exact path="/tpa_error/" component={TpaErrorComponent} />
              <Route
                exact
                path="/maintenance/"
                component={MaintenanceComponent}
              />
              <Route
                render={() => <div> Sorry, this page does not exist. </div>}
              />
            </Switch>
          </div>
        </Router>
      </div>
    );
  }

  updateDimensions(withSetState = false) {
    if (is_electron_browser()) {
      return;
    }
    let height = window.innerHeight + "px";
    if (window.location.pathname === "/profile/") {
      height = window.innerHeight + "px";
    }

    if (withSetState) {
      this.setState({
        screen_height: height,
      });
    } else {
      this.state.screen_height = height;
    }
  }

  componentDidMount() {
    this.updateDimensions(true);
    window.addEventListener("resize", this.updateDimensions.bind(this));
    /*if (!(window as any).caisseAvailable) {
      (this.props as any).dispatchAction({ type: "CAISSE_DISCONNECTED" });
    } else {
      (this.props as any).dispatchAction({ type: "CAISSE_CONNECTED" });
    }*/
  }

  componentWillUnmount() {
    window.removeEventListener("resize", this.updateDimensions.bind(this));
  }

  componentDidUpdate(prevProps) {
    if (
      (this.props as any).caisseConnected !== prevProps.caisseConnected &&
      (this.props as any).caisseConnected
    ) {
      Tracker.redirect_to_begin();
    }
  }
}

function mapStateToProps(state: any) {
  if (this_component) {
    this_component.adapt_screen(state.handdicap_version);
  }
  return {
    handdicap_version: state.handdicap_version,
    caisseConnected: caisseConnectedSelector(state),
  };
}

function mapDispatchToProps(dispatch: any) {
  return {
    ...bindActionCreators(
      {
        update_data,
        activeHandicappedVersion,
        update_product,
      },
      dispatch
    ),
    dispatchAction: (action) => dispatch(action),
  };
}

export default connect(mapStateToProps, mapDispatchToProps)(App);
