
import React from 'react';
import { withTranslation, WithTranslation } from 'react-i18next';
import { connect } from 'react-redux';
import { bindActionCreators } from 'redux';
import CloserTimer from '../../../libs/time';
import { activeHandicappedVersion, goToPath } from './../../../actions/index';
import Tracker from './../../../libs/tracker';

let this_component;
interface Props extends WithTranslation {
  activeHandicappedVersion: Function,
  handdicap_version: any,
  goToPath: Function,
};

class TimerPopinComponent extends React.Component<Props> {
  constructor(props: any) {
    super(props);
    (window as any).components.TimerPopinComponent = this;
  }

  state: any = {
    show: false,
    wait_in_second: 0
  }

  open() {
    if (this.state.show || CloserTimer.blocked) { return; }
    this.setState({
      'show': true,
      'wait_in_second': 10,
    });

    let decompt = setInterval(() => {
      if (!this.state.show) {
        clearInterval(decompt);
        return;
      }
      let wait_in_second = this.state.wait_in_second - 1
      if (wait_in_second === 0) {
        clearInterval(decompt);
        this.onHide();
        return Tracker.redirect_to_begin();
      }
      this.setState({
        wait_in_second: wait_in_second
      })
    }, 1 * 1000);
  }

  onHide() {
    // this.state.go_to.closed = true;
    this.setState({
      'show': false,
    });
  }

  render_popin() {
    if (!this.state.show) { return (<></>); }
    const { t } = this.props;
    return (
      <>
        <div className="background_popin_timer">
        </div>
        <div className="pop_timer">
          <h1>{t`timer.warnMsgPart1`}</h1>
          <h2>{t('timer.warnMsgPart2', { seconds: this.state.wait_in_second})}</h2>
          <button onClick={(() => this.onHide())}>{t`common.cancel`}</button>
        </div>
      </>
    )
  }

  render(): JSX.Element {
    this_component = this;
    return (
      <>
        {this.render_popin()}
      </>
    );
  }

  componentDidMount() {

  }
}

function mapStateToProps(state: any) {
  if (this_component !== undefined && this_component.state.pathname !== window.location.pathname) {

  }
  return {
    handdicap_version: state.handdicap_version,
  };
}


function mapDispatchToProps(dispatch: any) {
  return bindActionCreators({
    activeHandicappedVersion,
    goToPath
  }, dispatch);
}

export default connect(mapStateToProps, mapDispatchToProps)(withTranslation()(TimerPopinComponent));
